import React, { useState } from 'react';

const TEAM = [
  { id: 1, name: 'Sarah Connor', active: true },
  { id: 2, name: 'John Doe', active: false },
  { id: 3, name: 'Maya Lin', active: true },
  { id: 4, name: 'David Kim', active: false }
];

export default function App() {
  const [onlyActive, setOnlyActive] = useState(true);

  const visibleMembers = TEAM.filter(member => !onlyActive || member.active);

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2>Team Roster</h2>
      <button 
        id="toggle-btn" 
        className="btn-secondary" 
        onClick={() => setOnlyActive(!onlyActive)}
      >
        {onlyActive ? 'Show All Members' : 'Show Only Active'}
      </button>

      <ul id="member-list" style={{ marginTop: '16px' }}>
        {visibleMembers.map(m => (
          <li key={m.id} className="member-item">
            {m.name} {m.active ? '🟢 (Active)' : '⚪ (Offline)'}
          </li>
        ))}
      </ul>
    </div>
  );
}

