reactExercise.solution:
import React, { useState } from 'react';

const INITIAL_CART = [
  { id: 'p1', name: 'Mechanical Keyboard', price: 120, qty: 1 },
  { id: 'p2', name: 'Wireless Mouse', price: 45, qty: 2 },
  { id: 'p3', name: 'USB-C Cable', price: 15, qty: 3 }
];

export default function App() {
  const [cart] = useState(INITIAL_CART);

  const grandTotal = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2>Order Summary</h2>
      <ul>
        {cart.map(item => (
          <li key={item.id}>
            {item.name} - ${item.price} x {item.qty}
          </li>
        ))}
      </ul>
      <h3 id="grand-total">Total: ${grandTotal}</h3>
    </div>
  );
}
